StoreDto StoreDto::fromJson(const json &j) {
  StoreDto storeDto;
  storeDto.hash = StringUtils::getStringOr(j, "hash");
  // The explicit uint64_t template argument matters: a 0.0 default would
  // deserialize through double, quantizing nanosecond since values (~1.7e18,
  // beyond double's 2^53 integer precision) to ~256 ns granularity.
  storeDto.since = j.value<uint64_t>("since", 0);
  storeDto.data = StringUtils::getStringOr(j, "data");
  storeDto.m_streamer_info = StringUtils::getStringOr(j, "streamerInfo");
  return storeDto;
}
